<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { adminApi } from '../api/admin'
import PaginationBar from '../components/PaginationBar.vue'
const logs=ref<any[]>([]),total=ref(0),action=ref(''),resourceType=ref(''),loading=ref(false),error=ref(''),selected=ref<any>(null),page=ref(1),pageSize=ref(10)
const actionLabel=(value:string)=>({submit:'提交',settle:'审核通过',reject:'审核拒绝',approve:'通过',update:'更新',soft_delete:'软删除',restore:'恢复',update_roles:'修改角色',update_status:'更新状态'} as Record<string,string>)[value]||value
const statusLabel=(value:string)=>({pending_confirmation:'待客户确认',pending_review:'待审核',executed:'已成交',settled:'已结算',rejected:'已拒绝',cancelled:'已取消',open:'待处理',resolved:'已解决'} as Record<string,string>)[value]||value||'—'
async function load(){loading.value=true;try{const r=(await adminApi.auditLogs(action.value,resourceType.value,pageSize.value,(page.value-1)*pageSize.value)).data.data;logs.value=r.items;total.value=r.total}catch(e:any){error.value=e.response?.data?.detail?.message||e.message}finally{loading.value=false}}
function showDetail(log:any){selected.value=log}function go(n:number){page.value=Math.max(1,n);load()}function changeSize(n:number){pageSize.value=n;page.value=1;load()}onMounted(load)
</script>
<template><section class="table-module"><div class="module-header"><div><span class="module-kicker">AUDIT TRAIL</span><h2>审计查询</h2><p>展示客户、业务对象和状态，唯一 ID 仅用于追踪。</p></div><span class="table-summary">共 {{total}} 条</span></div><div class="module-tools"><select v-model="action" @change="load"><option value="">全部操作</option><option value="submit">提交</option><option value="settle">审核通过</option><option value="reject">审核拒绝</option><option value="soft_delete">软删除</option><option value="restore">恢复</option></select><select v-model="resourceType" @change="load"><option value="">全部对象</option><option value="order">订单</option><option value="business_operation">业务操作</option><option value="risk_alert">风险预警</option><option value="user">用户</option><option value="product">产品</option></select><button class="table-action" @click="load">刷新</button></div><p v-if="error" class="error">{{error}}</p><div v-if="loading" class="empty">正在读取审计记录…</div><div v-else class="module-table-wrap wide-table"><table class="admin-table compact-table"><thead><tr><th>时间</th><th>操作</th><th>客户</th><th>业务对象</th><th>状态</th><th>操作人</th><th>详情</th></tr></thead><tbody><tr v-for="log in logs" :key="log.id"><td class="time-cell">{{log.created_at}}</td><td>{{actionLabel(log.action)}}</td><td><strong>{{log.customer_name||'—'}}</strong><small class="audit-sub">{{log.customer_username||''}}</small></td><td><strong>{{log.business_type||log.resource_name||log.resource_type}}</strong><small class="audit-sub">{{log.product_name||log.business_reference}}</small></td><td><span class="table-tag">{{statusLabel(log.business_status)}}</span></td><td>{{log.actor_name||'系统'}}</td><td><button class="table-action" @click="showDetail(log)">查看详情</button></td></tr><tr v-if="!logs.length"><td colspan="7" class="table-empty">暂无审计记录</td></tr></tbody></table></div><PaginationBar :page="page" :page-size="pageSize" :total="total" @change="go" @size-change="changeSize"/><Teleport to="body"><div v-if="selected" class="admin-modal-backdrop" @click.self="selected=null"><div class="admin-modal detail-modal"><div class="modal-header"><div><span class="module-kicker">AUDIT DETAIL</span><h3>审计记录详情</h3></div><button class="modal-close" @click="selected=null">×</button></div><dl class="detail-grid"><dt>时间</dt><dd>{{selected.created_at}}</dd><dt>操作</dt><dd>{{actionLabel(selected.action)}}</dd><dt>客户</dt><dd>{{selected.customer_name||'—'}} {{selected.customer_username?`（${selected.customer_username}）`:''}}</dd><dt>业务类型</dt><dd>{{selected.business_type||selected.resource_type}}</dd><dt>业务对象</dt><dd>{{selected.product_name||selected.business_reference||selected.resource_name}}</dd><dt>业务状态</dt><dd>{{statusLabel(selected.business_status)}}</dd><dt>资源 ID</dt><dd class="mono">{{selected.resource_id}}</dd><dt>操作人</dt><dd>{{selected.actor_name||'系统'}}</dd><dt>详情</dt><dd class="detail-json">{{selected.detail||'无'}}</dd></dl></div></div></Teleport></section></template>
